def main():
    print(f"Translating {len(DOC_FILES)} markdown documentation files to Japanese...")
    for rel_path in DOC_FILES:
        build_localized_file(rel_path, "ja", TRANSLATIONS_JA)

    # Verification
    docs_dir = os.path.join(REPO_ROOT, "docs")
    ja_dir = os.path.join(docs_dir, "ja")
    generated_files = []
    for root, dirs, files in os.walk(ja_dir):
        for file in files:
            if file.endswith(".md"):
                rel_path = os.path.relpath(os.path.join(root, file), ja_dir)
                generated_files.append(rel_path.replace(os.sep, "/"))

    generated_files.sort()
    print(f"Successfully generated {len(generated_files)} Japanese documentation files in docs/ja/.")
    if len(generated_files) == len(DOC_FILES):
        print("Verification passed: All 59 documentation files generated successfully.")
    else:
        print(f"Verification mismatch: Expected {len(DOC_FILES)} files, but found {len(generated_files)}.")

if __name__ == "__main__":
    main()
